package com.ridex.location.dto.request;
import jakarta.validation.*; import org.junit.jupiter.api.*; import java.util.Set; import static org.junit.jupiter.api.Assertions.*;
class UpdateLocationRequestValidationTest { Validator validator; @BeforeEach void setup(){validator=Validation.buildDefaultValidatorFactory().getValidator();} @Test void acceptsValidCoordinateBoundaries(){assertTrue(validator.validate(new UpdateLocationRequest(90.0,180.0)).isEmpty());assertTrue(validator.validate(new UpdateLocationRequest(-90.0,-180.0)).isEmpty());} @Test void rejectsLatitudeOutsideRange(){assertFalse(validator.validate(new UpdateLocationRequest(90.1,0.0)).isEmpty());assertFalse(validator.validate(new UpdateLocationRequest(-90.1,0.0)).isEmpty());} @Test void rejectsLongitudeOutsideRange(){assertFalse(validator.validate(new UpdateLocationRequest(0.0,180.1)).isEmpty());assertFalse(validator.validate(new UpdateLocationRequest(0.0,-180.1)).isEmpty());} @Test void rejectsNullCoordinates(){assertEquals(2,validator.validate(new UpdateLocationRequest(null,null)).size());} }
